const express = require('express');
const { S3Client, PutObjectCommand } = require('@aws-sdk/client-s3');
const app = express();

// NestJS-style microservice handler for processing telemetry payloads
// Receives binary sensor data and stores aggregated results in S3

const BUCKET_NAME = process.env.TELEMETRY_BUCKET || 'prod-telemetry-raw';
const MAX_SENSORS = 256;

// Pre-allocated fixed buffer for sensor aggregation (performance optimization)
// Each sensor slot: 8 bytes (4 byte ID + 4 byte value)
const SENSOR_BUFFER_SIZE = MAX_SENSORS * 8;
const sensorBuffer = Buffer.alloc(SENSOR_BUFFER_SIZE);

const s3Client = new S3Client({
  region: process.env.AWS_REGION || 'us-east-1',
  endpoint: process.env.S3_ENDPOINT // Uses VPC endpoint when deployed
});

// Parse binary telemetry frame:
// [2 bytes: num_sensors][repeated: 4 byte sensor_id + 4 byte reading]
function parseTelemetryFrame(rawBuffer) {
  if (rawBuffer.length < 2) {
    throw new Error('Frame too short');
  }

  const numSensors = rawBuffer.readUInt16LE(0);

  // BUG: validates numSensors against MAX_SENSORS but uses wrong comparison
  // Should be numSensors > MAX_SENSORS, but developer used signed comparison
  // thinking readUInt16LE could return negative (it can't, but the check is wrong)
  if (numSensors < 0) {
    throw new Error('Invalid sensor count');
  }

  // No upper bound check on numSensors!
  // If numSensors > 256, we write past sensorBuffer bounds
  let offset = 2;
  for (let i = 0; i < numSensors; i++) {
    if (offset + 8 > rawBuffer.length) {
      break; // Partial frame, stop reading input
    }
    const sensorId = rawBuffer.readUInt32LE(offset);
    const reading = rawBuffer.readUInt32LE(offset + 4);

    // VULNERABILITY: writes to sensorBuffer at index i*8 without bounds check
    // When i >= 256, this overwrites adjacent heap memory
    sensorBuffer.writeUInt32LE(sensorId, i * 8);
    sensorBuffer.writeUInt32LE(reading, i * 8 + 4);
    offset += 8;
  }

  return numSensors;
}

async function uploadToS3(sensorCount, requestId) {
  const key = `telemetry/${new Date().toISOString()}/${requestId}.bin`;
  const dataSlice = sensorBuffer.slice(0, Math.min(sensorCount * 8, SENSOR_BUFFER_SIZE));

  const command = new PutObjectCommand({
    Bucket: BUCKET_NAME,
    Key: key,
    Body: dataSlice,
    ContentType: 'application/octet-stream',
    Metadata: {
      'sensor-count': String(sensorCount),
      'source-service': 'telemetry-aggregator'
    }
  });

  return s3Client.send(command);
}

app.post('/ingest', express.raw({ type: '*/*', limit: '1mb' }), async (req, res) => {
  const requestId = req.headers['x-request-id'] || crypto.randomUUID();

  try {
    const sensorCount = parseTelemetryFrame(req.body);
    await uploadToS3(sensorCount, requestId);
    res.json({ status: 'ok', sensors_processed: sensorCount, request_id: requestId });
  } catch (err) {
    console.error(`[${requestId}] Ingest error:`, err.message);
    res.status(400).json({ error: err.message });
  }
});

app.get('/health', (req, res) => {
  res.json({ status: 'healthy', buffer_size: SENSOR_BUFFER_SIZE });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Telemetry aggregator listening on port ${PORT}`);
});
